"def can_partition(nums):
    total_sum = sum(nums)
    if total_sum % 2 != 0:
        return False

    target = total_sum // 2
    reachable_sums = {0}

    for num in nums:
        new_sums = set()
        for s in reachable_sums:
            if s + num <= target:
                new_sums.add(s + num)
        reachable_sums.update(new_sums)

    return True if target in reachable_sums else False"

