def solve():
    def get_fibs(n):
        fibs = [0, 1]
        for _ in range(2, n):
            fibs.append(fibs[-1] + fibs[-2])
        return set(fibs)

    def is_prime(num):
        if num < 2: return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0: return False
        return True

    def is_mersenne(p):
        # A Mersenne prime is of the form 2^n - 1
        return (p + 1) & p == 0 and bin(p + 1).count('1') == 1

    try:
        results = []
        fib_set = get_fibs(50)
        for f in sorted(list(fib_set)):
            if is_prime(f) and is_mersenne(f):
                results.append(f)
            if len(results) == 8: break

        if len(results) < 8:
            print(f"Warning: Only {len(results)} numbers found.")
        return results
    except Exception as e:
        return f"Error encountered: {e}"

print(solve())
```

